const DAY_IN_MILLISECONDS = 86_400_000
const RELATIVE_TIME_FORMATTER = new Intl.RelativeTimeFormat("en-US", { numeric: "auto" })
const DATE_TIME_FORMATTERS = new Map()

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / DAY_IN_MILLISECONDS)
}

export function beginningOfDay(date) {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()))
}

export function formatLocalTime(date, format = "time-or-date", relativeTo = new Date()) {
  switch (format.replaceAll("_", "-")) {
  case "time-or-date":
    return formatTimeOrDate(date, relativeTo)
  case "time-ago":
    return formatTimeAgo(date, relativeTo)
  case "time-until":
    return formatTimeUntil(date, relativeTo)
  case "time":
    return formatDateTime(date, { hour: "numeric", minute: "2-digit" })
  case "date":
    return formatDate(date, relativeTo)
  case "date-with-year":
    return formatDateTime(date, { month: "short", day: "numeric", year: "numeric" })
  case "long-date":
    return formatLongDate(date, relativeTo)
  case "date-time":
    return formatDateTime(date, {
      month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit"
    })
  default:
    throw new Error(`Unknown local time format: ${format}`)
  }
}

function formatTimeOrDate(date, relativeTo) {
  const differenceInDays = signedDifferenceInDays(relativeTo, date)

  if (differenceInDays === 0) {
    return formatLocalTime(date, "time", relativeTo)
  } else if (Math.abs(differenceInDays) < 7) {
    return RELATIVE_TIME_FORMATTER.format(differenceInDays, "day")
  } else {
    return formatDate(date, relativeTo)
  }
}

function formatTimeAgo(date, relativeTo) {
  const differenceInDays = signedDifferenceInDays(relativeTo, date)

  if (differenceInDays !== 0) {
    return formatRelativeDays(differenceInDays)
  } else {
    const differenceInMilliseconds = date - relativeTo
    const absoluteDifference = Math.abs(differenceInMilliseconds)

    if (absoluteDifference < 60_000) {
      return RELATIVE_TIME_FORMATTER.format(0, "second")
    } else if (absoluteDifference < 3_600_000) {
      return RELATIVE_TIME_FORMATTER.format(relativeValue(differenceInMilliseconds, 60_000), "minute")
    } else {
      return RELATIVE_TIME_FORMATTER.format(relativeValue(differenceInMilliseconds, 3_600_000), "hour")
    }
  }
}

function formatTimeUntil(date, relativeTo) {
  return RELATIVE_TIME_FORMATTER.format(signedDifferenceInDays(relativeTo, date), "day")
}

function formatRelativeDays(differenceInDays) {
  const absoluteDifference = Math.abs(differenceInDays)

  if (absoluteDifference < 30) {
    return RELATIVE_TIME_FORMATTER.format(differenceInDays, "day")
  } else if (absoluteDifference < 365) {
    return RELATIVE_TIME_FORMATTER.format(relativeValue(differenceInDays, 30), "month")
  } else {
    return RELATIVE_TIME_FORMATTER.format(relativeValue(differenceInDays, 365), "year")
  }
}

function relativeValue(difference, unitSize) {
  return Math.sign(difference) * Math.round(Math.abs(difference) / unitSize)
}

function formatDate(date, relativeTo) {
  const options = { month: "short", day: "numeric" }
  if (date.getFullYear() !== relativeTo.getFullYear()) options.year = "numeric"

  return formatDateTime(date, options)
}

function formatLongDate(date, relativeTo) {
  const options = { weekday: "long", month: "long", day: "numeric" }
  if (date.getFullYear() !== relativeTo.getFullYear()) options.year = "numeric"

  return formatDateTime(date, options)
}

function formatDateTime(date, options) {
  const key = JSON.stringify(options)
  let formatter = DATE_TIME_FORMATTERS.get(key)

  if (!formatter) {
    formatter = new Intl.DateTimeFormat("en-US", options)
    DATE_TIME_FORMATTERS.set(key, formatter)
  }

  return formatter.format(date)
}
